B=Path('batches/glossary_batch_product_manager'); S=B/'working/coverage_sources'
C=json.loads((B/'extracted_concepts.json').read_text())['concepts']
L={x['concept_id']:x for x in json.loads((B/'registry_lookup.json').read_text())['lookups']}
SN=json.loads((B/'concept_evidence_registry_snapshot.json').read_text())['entries']
PACK=json.loads((B/'product_manager.source_pack.json').read_text())
IDX={x['source_id']:x['url_or_citation'] for x in json.loads((S/'fetch_index.json').read_text())}
IDX.update({x['source_id']:x['url_or_citation'] for x in PACK['sources']})
ROOTS={'atlassian.com':'atlassian_agile','productplan.com':'productplan_glossary','nngroup.com':'nngroup_articles','romanpichler.com':'pichler_blog','amplitude.com':'amplitude_playbook','svpg.com':'svpg_articles','scrumguides.org':'scrum_guide','foundationinc.co':'https://foundationinc.co/lab/tam-sam-som'}
def ref(key,heading=None):
 assert (S/(key+'.txt')).exists(),key
 u=IDX[key]; host=urlparse(u).hostname
 root=next(v for k,v in ROOTS.items() if host==k or host.endswith('.'+k))
 title=(S/(key+'.txt')).read_text().splitlines()[0]
 return root+'#'+u+' :: '+(heading if heading and heading.lower() in (S/(key+'.txt')).read_text().lower() else title)
def F(text,key,heading=None):return (text,ref(key,heading))
DATA={}
def add(i,facts,mis=(),conf=(),exception=None,optional=()):
 assert i not in DATA
 DATA[i]=(facts,mis,conf,exception,optional)
