add(4,[F('A product strategy is a high-level plan connecting product direction, goals, and initiatives.','atl_product-strategy','What is a product strategy?'),F('Strategy identifies the target market and customer needs the product will address.','atl_product-strategy','Key components of a product strategy'),F('Set measurable goals and select initiatives based on their likely impact and fit with the product direction.','atl_product-strategy','Key components of a product strategy'),F('Check a proposed initiative against the chosen audience, customer needs, and goals before including it in the strategy.','pichler_my-product-strategy-model','My Product Strategy Model')],conf=['Product vision','Product positioning'])
